import{_ as a,c as r,o as s,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Performance and Diagnostics — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-11-performance-diagnostics.md","filePath":"practice/node-js/module-11-performance-diagnostics.md"}'),t={name:"practice/node-js/module-11-performance-diagnostics.md"};function o(n,e,l,c,d,p){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="performance-and-diagnostics-—-practice" tabindex="-1">Performance and Diagnostics — practice <a class="header-anchor" href="#performance-and-diagnostics-—-practice" aria-label="Permalink to “Performance and Diagnostics — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-11-performance-diagnostics.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h2 id="_15-practice-exercises" tabindex="-1"><span class="hub-section-number">1 </span>Practice exercises <a class="header-anchor" href="#_15-practice-exercises" aria-label="Permalink to “1 Practice exercises”">​</a></h2><h3 id="exercise-1-event-loop-stall" tabindex="-1"><span class="hub-section-number">1.1 </span>Exercise 1: Event-loop stall <a class="header-anchor" href="#exercise-1-event-loop-stall" aria-label="Permalink to “1.1 Exercise 1: Event-loop stall”">​</a></h3><p>A route parses a very large payload and performs a nested loop. Under load, unrelated health requests also become slow.</p><p>Investigate:</p><ul><li>which measurements prove event-loop blocking;</li><li>which code appears in a CPU profile;</li><li>whether bounds, a better algorithm, streaming, or workers are appropriate;</li><li>how you will prove the fix.</li></ul><h3 id="exercise-2-the-database-is-slow-report" tabindex="-1"><span class="hub-section-number">1.2 </span>Exercise 2: The “database is slow” report <a class="header-anchor" href="#exercise-2-the-database-is-slow-report" aria-label="Permalink to “1.2 Exercise 2: The “database is slow” report”">​</a></h3><p>Application traces show 900 ms around a database helper. The database reports that the query executes in 25 ms.</p><p>Investigate pool acquisition, transaction duration, leaked clients, and total connections across instances. Explain why increasing the pool might make the system worse.</p><h3 id="exercise-3-slow-memory-growth" tabindex="-1"><span class="hub-section-number">1.3 </span>Exercise 3: Slow memory growth <a class="header-anchor" href="#exercise-3-slow-memory-growth" aria-label="Permalink to “1.3 Exercise 3: Slow memory growth”">​</a></h3><p>Heap usage rises by 30 MB each hour. Traffic stays constant. A map stores request status by correlation ID.</p><p>Find the ownership rule that is missing. Add deletion or a bounded expiry policy. Verify the fix with a soak test and post-GC heap trend.</p><h3 id="exercise-4-misleading-load-test" tabindex="-1"><span class="hub-section-number">1.4 </span>Exercise 4: Misleading load test <a class="header-anchor" href="#exercise-4-misleading-load-test" aria-label="Permalink to “1.4 Exercise 4: Misleading load test”">​</a></h3><p>A closed-model test reports good p99 latency at 100 virtual users. Production receives a fixed burst of 2,000 events per second and develops a queue.</p><p>Explain the mismatch. Design a test that controls arrival rate and measures queue delay, rejection, and recovery.</p><h3 id="exercise-5-worker-pool-design" tabindex="-1"><span class="hub-section-number">1.5 </span>Exercise 5: Worker-pool design <a class="header-anchor" href="#exercise-5-worker-pool-design" aria-label="Permalink to “1.5 Exercise 5: Worker-pool design”">​</a></h3><p>PDF generation blocks the event loop for 400 ms. Design a bounded worker pool. Define queue capacity, timeout behavior, crash replacement, cancellation, correlation, and graceful shutdown.</p><p>For every exercise, include the evidence that would falsify your first hypothesis. A strong diagnosis can change direction when measurements disagree.</p><hr><h2 id="_16-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_16-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><h3 id="measurement" tabindex="-1"><span class="hub-section-number">2.1 </span>Measurement <a class="header-anchor" href="#measurement" aria-label="Permalink to “2.1 Measurement”">​</a></h3><ul><li>[ ] Turn a vague performance complaint into a measurable target.</li><li>[ ] Record a reproducible baseline before changing code.</li><li>[ ] Distinguish throughput, latency, concurrency, utilization, and saturation.</li><li>[ ] Use p50, p95, and p99 instead of relying only on averages.</li><li>[ ] Explain coordinated omission and open versus closed load models.</li></ul><h3 id="node-js-runtime" tabindex="-1"><span class="hub-section-number">2.2 </span>Node.js runtime <a class="header-anchor" href="#node-js-runtime" aria-label="Permalink to “2.2 Node.js runtime”">​</a></h3><ul><li>[ ] Distinguish CPU-bound work from asynchronous I/O waits.</li><li>[ ] Measure event-loop delay and event-loop utilization.</li><li>[ ] Recognize common event-loop blockers.</li><li>[ ] Interpret RSS, heap, external memory, and buffers separately.</li><li>[ ] Diagnose a leak from trends and retained ownership, not one memory reading.</li><li>[ ] Use CPU and heap profiling safely.</li></ul><h3 id="dependencies-and-capacity" tabindex="-1"><span class="hub-section-number">2.3 </span>Dependencies and capacity <a class="header-anchor" href="#dependencies-and-capacity" aria-label="Permalink to “2.3 Dependencies and capacity”">​</a></h3><ul><li>[ ] Separate database pool wait from query execution time.</li><li>[ ] Read query plans and investigate locks, result size, and N+1 patterns.</li><li>[ ] Budget total database connections across all service instances.</li><li>[ ] Bound queues and concurrency before overload consumes memory.</li><li>[ ] Choose workers only for measured CPU-intensive JavaScript.</li></ul><h3 id="verification-and-observability" tabindex="-1"><span class="hub-section-number">2.4 </span>Verification and observability <a class="header-anchor" href="#verification-and-observability" aria-label="Permalink to “2.4 Verification and observability”">​</a></h3><ul><li>[ ] Design representative baseline, load, stress, spike, soak, and failure tests.</li><li>[ ] Monitor the load generator as well as the target.</li><li>[ ] Correlate logs, metrics, traces, and profiles.</li><li>[ ] Avoid high-cardinality metric labels.</li><li>[ ] Re-run the same experiment after each focused change.</li><li>[ ] Confirm correctness and error rates as well as speed.</li></ul><h2 id="executable-lifecycle-and-failure-checks" tabindex="-1"><span class="hub-section-number">3 </span>Executable lifecycle and failure checks <a class="header-anchor" href="#executable-lifecycle-and-failure-checks" aria-label="Permalink to “3 Executable lifecycle and failure checks”">​</a></h2><p>Node24.18.0/TypeScript5.9.3 baseline, official APIs checked2026-10-25. Extract loop-diagnostics.ts and measured-db.ts into the isolated practice project. Observe at least one real reporting tick, call stop twice and require no later observation; inject a throwing sink and require stopped=true/no further ticks. Treat measured values as smoke-test observations, not a workload benchmark or proof of CPU/GC behavior. Check invalid interval values and that shutdown disposes all owned diagnostics.</p><p>For the DB port test acquisition success/failure, query success/failure, throwing telemetry, release failure and combined query+release failure. Require phase labels/outcomes and nonnegative finite durations, one release per acquired connection and unchanged result/error identity except the documented AggregateError. No raw SQL/parameters/private error text may enter observation fields. Retain actual worker zero-exit/no-result, crash, invalid message, timeout, abort and post-result open-handle tests from the shared module02 helper; no duplicate broken worker wrapper belongs here.</p><p><strong>Learner practice:</strong> instrument an actual owned service/DB adapter, reproduce a representative workload, measure pool versus query wait, collect a short protected CPU/heap profile only when evidence justifies it and run the same workload after a focused change. Native profiling/GC/leak conclusions, pool capacity sizing and production gain are not established by these lifecycle tests. Memory counters overlap and percentiles need enough samples. <a href="https://nodejs.org/download/release/v24.18.0/docs/api/perf_hooks.html" target="_blank" rel="noreferrer">Node24 perf_hooks</a>, <a href="https://nodejs.org/download/release/v24.18.0/docs/api/process.html#processmemoryusage" target="_blank" rel="noreferrer">memoryUsage categories</a>.</p>',34)])])}const m=a(t,[["render",o]]);export{u as __pageData,m as default};
